package com.sobrenaturaldirector.composition.validation;

import java.util.*;
import com.sobrenaturaldirector.composition.model.*;

public final class CompositionValidator {private CompositionValidator(){}public static List<String> validate(StructureBlueprint b){List<String>e=new ArrayList<String>();if(b==null)return Collections.singletonList("structure missing");Map<String,StructureNode> n=new HashMap<String,StructureNode>();for(StructureNode x:b.getNodes()){if(n.put(x.getId(),x)!=null)e.add("duplicate node "+x.getId());if(Math.abs(x.getPosition().getX())>64||Math.abs(x.getPosition().getY())>32||Math.abs(x.getPosition().getZ())>64)e.add("node out of bounds "+x.getId());}Set<String> edges=new HashSet<String>();Map<String,List<String>> g=new HashMap<String,List<String>>();for(StructureConnector c:b.getConnectors()){if(!n.containsKey(c.getFrom())||!n.containsKey(c.getTo()))e.add("connector endpoint missing "+c.getId());if(!edges.add(c.getId()))e.add("duplicate connector "+c.getId());if(n.containsKey(c.getFrom())&&n.containsKey(c.getTo())){g.computeIfAbsent(c.getFrom(),k->new ArrayList<String>()).add(c.getTo());g.computeIfAbsent(c.getTo(),k->new ArrayList<String>()).add(c.getFrom());}}String start=null;for(StructureNode x:b.getNodes())if(x.getType()==StructureNodeType.ENTRANCE){if(start!=null)e.add("multiple entrances");start=x.getId();}if(start==null)e.add("entrance missing");Set<String>seen=new HashSet<String>();if(start!=null){Deque<String>q=new ArrayDeque<String>();q.add(start);while(!q.isEmpty()){String x=q.remove();if(seen.add(x))for(String y:g.getOrDefault(x,Collections.<String>emptyList()))q.add(y);}}for(StructureNode x:b.getNodes())if(x.isMandatory()&&!seen.contains(x.getId()))e.add("mandatory node unreachable "+x.getId());for(String x:b.getCriticalPath())if(!seen.contains(x))e.add("critical path unreachable "+x);return e;}}
